package ru.murad.yourmarket.telegram.keyboard;
import java.util.*; import org.springframework.stereotype.Component; import org.telegram.telegrambots.meta.api.objects.replykeyboard.InlineKeyboardMarkup; import org.telegram.telegrambots.meta.api.objects.replykeyboard.buttons.*; import ru.murad.yourmarket.service.LocationCatalog;
@Component public class LocationKeyboardFactory { private static final int PAGE=10; private final LocationCatalog catalog; public LocationKeyboardFactory(LocationCatalog c){catalog=c;}
 public InlineKeyboardMarkup regions(int p){return page(catalog.regions(),p,"ad:loc:r:",true);} public InlineKeyboardMarkup cities(String r,int p){return page(catalog.cities(r),p,"ad:loc:c:",false);} public InlineKeyboardMarkup regionSearch(String q){return choices(catalog.searchRegions(q),"ad:loc:r:","ad:loc:regions");} public InlineKeyboardMarkup citySearch(String r,String q){return choices(catalog.searchCities(r,q),"ad:loc:c:","ad:loc:cities");}
 private InlineKeyboardMarkup page(List<?> x,int request,String prefix,boolean region){int pages=Math.max(1,(x.size()+PAGE-1)/PAGE),p=Math.max(0,Math.min(request,pages-1)),from=p*PAGE,to=Math.min(x.size(),from+PAGE);List<InlineKeyboardRow> rows=rows(x.subList(from,to),prefix);rows.add(new InlineKeyboardRow(button(region?"🔎 Найти регион":"🔎 Найти город",region?"ad:loc:rs":"ad:loc:cs")));if(!region)rows.add(new InlineKeyboardRow(button("✏️ Другой населённый пункт","ad:loc:other"),button("⬅️ К регионам","ad:loc:regions")));if(pages>1)rows.add(new InlineKeyboardRow(button("⬅️", "ad:loc:"+(region?"rp:":"cp:")+Math.max(0,p-1)),button((p+1)+"/"+pages,"ad:loc:page"),button("➡️", "ad:loc:"+(region?"rp:":"cp:")+Math.min(pages-1,p+1))));return InlineKeyboardMarkup.builder().keyboard(rows).build();}
 private InlineKeyboardMarkup choices(List<?> x,String prefix,String back){List<InlineKeyboardRow> rows=rows(x,prefix);rows.add(new InlineKeyboardRow(button("⬅️ Назад",back)));return InlineKeyboardMarkup.builder().keyboard(rows).build();} private List<InlineKeyboardRow> rows(List<?> x,String p){List<InlineKeyboardRow> r=new ArrayList<>();for(int i=0;i<x.size();i+=2){InlineKeyboardButton a=item(x.get(i),p);r.add(i+1<x.size()?new InlineKeyboardRow(a,item(x.get(i+1),p)):new InlineKeyboardRow(a));}return r;} private InlineKeyboardButton item(Object x,String p){String code=x instanceof LocationCatalog.Region r?r.code():((LocationCatalog.City)x).code();String name=x instanceof LocationCatalog.Region r?r.name():((LocationCatalog.City)x).name();return button(name,p+code);} private InlineKeyboardButton button(String t,String d){return InlineKeyboardButton.builder().text(t).callbackData(d).build();}
}
